(685021, 71811, 11518, '<td valign="top">nice little house, the pic would have been better is it filled the frame...but then would it fit the challenge?  I don''t know.</td>', 'nice little house, the pic would have been better is it filled the frame...but then would it fit the challenge?  I don''t know.', '2004-04-26 01:06:21.000000', NULL, 1),
(685023, 71667, 11518, '<td valign="top">A little bit of fill-flash on the foreground monument would have made that pic better.</td>', 'A little bit of fill-flash on the foreground monument would have made that pic better.', '2004-04-26 01:07:12.000000', NULL, 1),
(685030, 72037, 11518, '<td valign="top">Very nice stop-motion but this does not quite fit the challenge...</td>', 'Very nice stop-motion but this does not quite fit the challenge...', '2004-04-26 01:08:31.000000', NULL, 1),
(685032, 72259, 327, '<td valign="top">Ha! Lived there in 1972. Moved on base at Great Lakes. It''s dead there? Is that why the cemetery? LOL I''ve been in worse places. The sky is a bit blown out in this shot, but not bad. Good luck in the challenge.</td>', 'Ha! Lived there in 1972. Moved on base at Great Lakes. It''s dead there? Is that why the cemetery? LOL I''ve been in worse places. The sky is a bit blown out in this shot, but not bad. Good luck in the challenge.', '2004-04-26 01:09:35.000000', NULL, 1),
(685033, 72164, 11518, '<td valign="top">Beautiful!  But it would have been better in landscape mode putting more emphasis on the houses.</td>', 'Beautiful!  But it would have been better in landscape mode putting more emphasis on the houses.', '2004-04-26 01:10:11.000000', NULL, 1),
(685036, 72071, 11518, '<td valign="top">A little bit over exposed.</td>', 'A little bit over exposed.', '2004-04-26 01:11:01.000000', NULL, 1),
(685038, 72338, 11518, '<td valign="top">Nice, but needs more depth of field and the background is somewhat overexposed.</td>', 'Nice, but needs more depth of field and the background is somewhat overexposed.', '2004-04-26 01:12:22.000000', NULL, 1),
(685040, 71883, 7969, '<td valign="top">hmm i live in bc, where is oak bay i need to come visit.  Great spot. Great shot too. Please send me directions from vancouver  : )</td>', 'hmm i live in bc, where is oak bay i need to come visit.  Great spot. Great shot too. Please send me directions from vancouver  : )', '2004-04-26 01:12:39.000000', NULL, 1),
(685041, 71124, 15381, '<td valign="top">i figured that night city shots would get it, but i just couldn''t bring myself to it...nice job 9</td>', 'i figured that night city shots would get it, but i just couldn''t bring myself to it...nice job 9', '2004-04-26 01:13:24.000000', NULL, 1),
(685043, 72042, 15381, '<td valign="top">too bad its a negative</td>', 'too bad its a negative', '2004-04-26 01:13:38.000000', NULL, 1),
(685046, 72138, 11518, '<td valign="top">Beautiful, but the mountains are a bit overexposed.  Easily corrected with the shadow/highlight adjustment in PS</td>', 'Beautiful, but the mountains are a bit overexposed.  Easily corrected with the shadow/highlight adjustment in PS', '2004-04-26 01:13:42.000000', NULL, 1),
(685049, 72093, 15381, '<td valign="top">horizon slants down to the left...otherwise cool photo</td>', 'horizon slants down to the left...otherwise cool photo', '2004-04-26 01:14:19.000000', NULL, 1),
(685052, 72208, 11518, '<td valign="top">Perspective is a bit crooked...did you shoot at an angle instead of straight on?</td>', 'Perspective is a bit crooked...did you shoot at an angle instead of straight on?', '2004-04-26 01:15:07.000000', NULL, 1),
(685053, 72068, 18194, '<td valign="top">Great photo</td>', 'Great photo', '2004-04-26 01:15:32.000000', NULL, 1),
