(685619, 72327, 13610, '<td valign="top">really interesting shot, look like an oasis.</td>', 'really interesting shot, look like an oasis.', '2004-04-26 11:15:08.000000', NULL, 1),
(685620, 72230, 327, '<td valign="top">I love this. 9 from me. I''m a sucker for anything  prairie, blowing grasses, wheat fields, rolling hills. :) Barbed wire!! nice shot, love the focus and tones.</td>', 'I love this. 9 from me. I''m a sucker for anything  prairie, blowing grasses, wheat fields, rolling hills. :) Barbed wire!! nice shot, love the focus and tones.', '2004-04-26 11:17:23.000000', NULL, 1),
(685621, 72336, 327, '<td valign="top">My top three!!!!! Yummy shot.</td>', 'My top three!!!!! Yummy shot.', '2004-04-26 11:17:51.000000', NULL, 1),
(685622, 72119, 14603, '<td valign="top">Nicely composed with good exposure...the sky really adds drama to the image.</td>', 'Nicely composed with good exposure...the sky really adds drama to the image.', '2004-04-26 11:18:05.000000', NULL, 1),
(685623, 72334, 13610, '<td valign="top">this is amazing.</td>', 'this is amazing.', '2004-04-26 11:18:10.000000', NULL, 1),
(685628, 71581, 14603, '<td valign="top">Good use of colour and composition.</td>', 'Good use of colour and composition.', '2004-04-26 11:22:14.000000', NULL, 1),
(685630, 72095, 13610, '<td valign="top">I always like the CN tower.</td>', 'I always like the CN tower.', '2004-04-26 11:23:27.000000', NULL, 1),
