(685632, 72338, 327, '<td valign="top">Well done. I like this - compliments only.</td>', 'Well done. I like this - compliments only.', '2004-04-26 11:24:44.000000', NULL, 1),
(685635, 72155, 13610, '<td valign="top">The too small size is wasting an amazing photo. the composition and  the lighting are really interesting but it''s just too small.</td>', 'The too small size is wasting an amazing photo. the composition and  the lighting are really interesting but it''s just too small.', '2004-04-26 11:25:17.000000', NULL, 1),
(685639, 72331, 327, '<td valign="top">''Prepare to come about!!''<br/> Nice shot, good perspective, color and action.</td>', '''Prepare to come about!!'' Nice shot, good perspective, color and action.', '2004-04-26 11:26:44.000000', NULL, 1),
(685642, 71957, 14603, '<td valign="top">Well composed and nicely exposed. I like the graduations in contrast.<br/>Good work</td>', 'Well composed and nicely exposed. I like the graduations in contrast.Good work', '2004-04-26 11:28:17.000000', NULL, 1),
(685660, 72334, 19608, '<td valign="top">So serene, nice find.  I love the old board lying on the seat.  Sky a bit hot.</td>', 'So serene, nice find.  I love the old board lying on the seat.  Sky a bit hot.', '2004-04-26 11:37:35.000000', NULL, 1),
(685663, 71717, 19608, '<td valign="top">Great blue in the water goes well with the golden trees.  Guess it''s Autumn there.  I would give you two additional points without that white sky.</td>', 'Great blue in the water goes well with the golden trees.  Guess it''s Autumn there.  I would give you two additional points without that white sky.', '2004-04-26 11:39:06.000000', NULL, 1),
(685664, 72094, 19608, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2004-04-26 11:39:39.000000', NULL, 1),
(685666, 72122, 19608, '<td valign="top">Very vibrant, nice composition.</td>', 'Very vibrant, nice composition.', '2004-04-26 11:40:18.000000', NULL, 1),
(685674, 72300, 19608, '<td valign="top">Nice find - and a great idea.  Photographically it doesn''t do much for me - but keep trying.  (Composition and lighting are my biggest concerns.)</td>', 'Nice find - and a great idea.  Photographically it doesn''t do much for me - but keep trying.  (Composition and lighting are my biggest concerns.)', '2004-04-26 11:46:31.000000', NULL, 1),
(685675, 72211, 19608, '<td valign="top">Perfect time of day - the colors really pop.  Composition very well done.</td>', 'Perfect time of day - the colors really pop.  Composition very well done.', '2004-04-26 11:47:09.000000', NULL, 1),
(685676, 72139, 19608, '<td valign="top">Great idea.  I''d like to see the top of the baby''s head  - and I would not center the subject.</td>', 'Great idea.  I''d like to see the top of the baby''s head  - and I would not center the subject.', '2004-04-26 11:48:16.000000', NULL, 1),
(685677, 72318, 19608, '<td valign="top">Nice composition.  Did you pay the models to wear the red coats?!!</td>', 'Nice composition.  Did you pay the models to wear the red coats?!!', '2004-04-26 11:48:52.000000', NULL, 1),
(685680, 71957, 13136, '<td valign="top">Interesting contrasts on this shot. Not sure , but I think it might have been better in color.</td>', 'Interesting contrasts on this shot. Not sure , but I think it might have been better in color.', '2004-04-26 11:53:19.000000', NULL, 1),
(685681, 72141, 13136, '<td valign="top">I love the contrast of old(buildings) and new (bridge).</td>', 'I love the contrast of old(buildings) and new (bridge).', '2004-04-26 11:54:13.000000', NULL, 1),
(685682, 72071, 13136, '<td valign="top">Nice shot, if a bit overexposed.</td>', 'Nice shot, if a bit overexposed.', '2004-04-26 11:55:23.000000', NULL, 1),
(685691, 72011, 13136, '<td valign="top">Colorado Springs. Beautiful park.</td>', 'Colorado Springs. Beautiful park.', '2004-04-26 12:07:54.000000', NULL, 1),
(685694, 72250, 13136, '<td valign="top">Good idea. Unfortunately, the overexposed left overshadows the dark bridge in the middle.</td>', 'Good idea. Unfortunately, the overexposed left overshadows the dark bridge in the middle.', '2004-04-26 12:09:51.000000', NULL, 1),
(685700, 72037, 13136, '<td valign="top">Great stop action shot.</td>', 'Great stop action shot.', '2004-04-26 12:19:09.000000', NULL, 1),
(685710, 71201, 11895, '<td valign="top">tilt is distracting, I''d try to rotate it so that the center looks vertical</td>', 'tilt is distracting, I''d try to rotate it so that the center looks vertical', '2004-04-26 12:23:58.000000', NULL, 1),
(685727, 71123, 14614, '<td valign="top">oh my -- just wonderful!  Haven''t seen them all yet but this will be one of my favorites!  Excellent use of proportion, light, and composition!</td>', 'oh my -- just wonderful!  Haven''t seen them all yet but this will be one of my favorites!  Excellent use of proportion, light, and composition!', '2004-04-26 12:35:23.000000', NULL, 1),
(685732, 71902, 14614, '<td valign="top">fab composition -- a bit punchier light would have made this good shot great</td>', 'fab composition -- a bit punchier light would have made this good shot great', '2004-04-26 12:36:39.000000', NULL, 1),
(685733, 72110, 14614, '<td valign="top">looks like a painting -- excellent use of color and light to create a serene mood.</td>', 'looks like a painting -- excellent use of color and light to create a serene mood.', '2004-04-26 12:38:06.000000', NULL, 1),
(685734, 72155, 14614, '<td valign="top">just too small for me to really get the details... too bad because you set up the composition well -- just wish it was larger</td>', 'just too small for me to really get the details... too bad because you set up the composition well -- just wish it was larger', '2004-04-26 12:39:17.000000', NULL, 1),
(685737, 71482, 14614, '<td valign="top">Can I go to your house??  Lovely composition and use of leading lines.</td>', 'Can I go to your house??  Lovely composition and use of leading lines.', '2004-04-26 12:40:07.000000', NULL, 1),
(685746, 72142, 13136, '<td valign="top">Nice shot. A touch of darkening/contrast would help a lot. And maybe a bit or rotate?</td>', 'Nice shot. A touch of darkening/contrast would help a lot. And maybe a bit or rotate?', '2004-04-26 12:46:40.000000', NULL, 1),
(685753, 72107, 14032, '<td valign="top">Pleasing subject matter and composition, however I''m not a fan of the color</td>', 'Pleasing subject matter and composition, however I''m not a fan of the color', '2004-04-26 12:51:08.000000', NULL, 1),
(685758, 72230, 14032, '<td valign="top">I love the simplicity of the picture...maybe (?) a little better if the center post wasn''t dead-center.  Still a great picture; love the B/W.  8</td>', 'I love the simplicity of the picture...maybe (?) a little better if the center post wasn''t dead-center.  Still a great picture; love the B/W.  8', '2004-04-26 12:56:03.000000', NULL, 1),
