(685976, 72093, 12827, '<td valign="top">nice but looks a little tilted</td>', 'nice but looks a little tilted', '2004-04-26 14:52:28.000000', NULL, 1),
(685977, 71240, 4285, '<td valign="top">I love the IR look. It adds a very surrealistic feel to the shot. Think I would have preferred to see the bridge more off center though. I gave this one of my highest votes of the challenge.</td>', 'I love the IR look. It adds a very surrealistic feel to the shot. Think I would have preferred to see the bridge more off center though. I gave this one of my highest votes of the challenge.', '2004-04-26 14:53:55.000000', NULL, 1),
