(685982, 72155, 4008, '<td valign="top">you need to learn how to keep a normal size image and still get it below 150 k, instructions are on this site. This is too small to judge.</td>', 'you need to learn how to keep a normal size image and still get it below 150 k, instructions are on this site. This is too small to judge.', '2004-04-26 14:55:53.000000', NULL, 1),
(685987, 72331, 16053, '<td valign="top">Excelent photo. Nice subject.</td>', 'Excelent photo. Nice subject.', '2004-04-26 14:57:10.000000', NULL, 1),
(685988, 72227, 4008, '<td valign="top">don''t know what happened, but the green looks very blurred, especially the larger patches. Composition could be improved to crop of the clutter on the left, up to the middle of the left tree.</td>', 'don''t know what happened, but the green looks very blurred, especially the larger patches. Composition could be improved to crop of the clutter on the left, up to the middle of the left tree.', '2004-04-26 14:58:18.000000', NULL, 1),
(685989, 71940, 11895, '<td valign="top">colors have that Velvia look, perhaps a bit oversaturated but a pleasant image</td>', 'colors have that Velvia look, perhaps a bit oversaturated but a pleasant image', '2004-04-26 14:58:45.000000', NULL, 1),
(685990, 71717, 811, '<td valign="top">That is an awesome looking place.  It looks like you have used NeatImage or some other noise reduction tool, and it might be a bit much in places.  Otherwise, good colors.</td>', 'That is an awesome looking place.  It looks like you have used NeatImage or some other noise reduction tool, and it might be a bit much in places.  Otherwise, good colors.', '2004-04-26 14:58:49.000000', NULL, 1),
(685993, 72170, 16053, '<td valign="top">A very strong shot. A bit dark alldough, but I don''t know if that is intencional to dramatize the picture. Nice work</td>', 'A very strong shot. A bit dark alldough, but I don''t know if that is intencional to dramatize the picture. Nice work', '2004-04-26 15:00:38.000000', NULL, 1),
(685994, 71361, 19446, '<td valign="top">I like the way you used the tree in the forground to frame the picture.</td>', 'I like the way you used the tree in the forground to frame the picture.', '2004-04-26 15:01:47.000000', NULL, 1),
(685999, 71672, 12827, '<td valign="top">you know, I kinda like the lens flare in this</td>', 'you know, I kinda like the lens flare in this', '2004-04-26 15:06:41.000000', NULL, 1),
(686010, 72037, 4008, '<td valign="top">Could have done with some more space so one could see the dirt and boots, but good catch anyway.</td>', 'Could have done with some more space so one could see the dirt and boots, but good catch anyway.', '2004-04-26 15:15:11.000000', NULL, 1),
(686011, 71993, 12827, '<td valign="top">I would like to see this with the foreground in focus</td>', 'I would like to see this with the foreground in focus', '2004-04-26 15:15:38.000000', NULL, 1),
(686012, 72102, 15642, '<td valign="top">The chain link fence distracts from an otherwise pretty shot</td>', 'The chain link fence distracts from an otherwise pretty shot', '2004-04-26 15:16:30.000000', NULL, 1),
