(686014, 71865, 15642, '<td valign="top">Trapped by what? The title throws me, but nice view.</td>', 'Trapped by what? The title throws me, but nice view.', '2004-04-26 15:16:55.000000', NULL, 1),
(686015, 72071, 15642, '<td valign="top">Pretentious title, and the star filter is a tad overdone.</td>', 'Pretentious title, and the star filter is a tad overdone.', '2004-04-26 15:17:51.000000', NULL, 1),
