(686036, 72331, 15920, '<td valign="top">Great photo, relation to the challenge is a little weak, but boats and wind always make me wish I was on vacation.  Excellent job on the sharpness.</td>', 'Great photo, relation to the challenge is a little weak, but boats and wind always make me wish I was on vacation.  Excellent job on the sharpness.', '2004-04-26 15:34:40.000000', NULL, 1),
(686041, 71883, 6597, '<td valign="top">great shot good composition  meets challenge 9</td>', 'great shot good composition  meets challenge 9', '2004-04-26 15:38:21.000000', NULL, 1),
(686046, 72242, 11895, '<td valign="top">I think this is over exposed, some of the stones are blown out and the greens look too yellowish, try agjusting the exposure compensation down a notch or two in the camera when shooting in bright sunlight</td>', 'I think this is over exposed, some of the stones are blown out and the greens look too yellowish, try agjusting the exposure compensation down a notch or two in the camera when shooting in bright sunlight', '2004-04-26 15:40:32.000000', NULL, 1),
(686047, 71634, 327, '<td valign="top">Poor Jeter...he can''t get wood on the ball right now. The perspective of this shot is awesome right down the line. Good work.</td>', 'Poor Jeter...he can''t get wood on the ball right now. The perspective of this shot is awesome right down the line. Good work.', '2004-04-26 15:40:47.000000', NULL, 1),
(686050, 71826, 6597, '<td valign="top">This certainly meets the challenge nice clouds 6</td>', 'This certainly meets the challenge nice clouds 6', '2004-04-26 15:43:38.000000', NULL, 1),
(686052, 72249, 6597, '<td valign="top">I like the  blur in the background 6</td>', 'I like the  blur in the background 6', '2004-04-26 15:45:14.000000', NULL, 1),
(686053, 72329, 327, '<td valign="top">I see the River Queen down there..good view from where you took this. Love it there......good post card shot.</td>', 'I see the River Queen down there..good view from where you took this. Love it there......good post card shot.', '2004-04-26 15:45:18.000000', NULL, 1),
