(686077, 72328, 327, '<td valign="top">Wow how Nevada has changed!!!! lol Pretty blue water, looks like a great area.</td>', 'Wow how Nevada has changed!!!! lol Pretty blue water, looks like a great area.', '2004-04-26 15:52:25.000000', NULL, 1),
(686078, 72264, 3087, '<td valign="top">Wow! Amazing capture.</td>', 'Wow! Amazing capture.', '2004-04-26 15:52:25.000000', NULL, 1),
