(686080, 72051, 11895, '<td valign="top">good colors</td>', 'good colors', '2004-04-26 15:53:06.000000', NULL, 1),
(686083, 72260, 3087, '<td valign="top">Well composed, mist creates a nice muted effect, gives a feeling of serenity.</td>', 'Well composed, mist creates a nice muted effect, gives a feeling of serenity.', '2004-04-26 15:54:25.000000', NULL, 1),
(686084, 71761, 327, '<td valign="top">Glacier! one of my favorite places. Lovely shot, and cool to see the ice break up. Love it there, lucky you!! Nice postcard shot.</td>', 'Glacier! one of my favorite places. Lovely shot, and cool to see the ice break up. Love it there, lucky you!! Nice postcard shot.', '2004-04-26 15:55:07.000000', NULL, 1),
(686085, 71927, 327, '<td valign="top">The roses, the water.....the girl, the baby, the hat.....really makes a nice shot. Nice, would like to of seen a bit more of the fountian. Maybe a bit brighter also.......?</td>', 'The roses, the water.....the girl, the baby, the hat.....really makes a nice shot. Nice, would like to of seen a bit more of the fountian. Maybe a bit brighter also.......?', '2004-04-26 15:56:53.000000', NULL, 1),
(686087, 71871, 327, '<td valign="top">Great humor. My mom used to say that (still does) all the time. LOL<br/>Fun shot. I don''t feel it shows me where you live but I do like the humor. :)</td>', 'Great humor. My mom used to say that (still does) all the time. LOLFun shot. I don''t feel it shows me where you live but I do like the humor. :)', '2004-04-26 15:57:46.000000', NULL, 1),
