INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(686092, 72239, 3087, '<td valign="top">A really interesting way of adding interest but let down a little by the weather - the sky is just too overcast to provide either the warmer lighting that would bring this alive or the interesting backdrop the would provide more colour.</td>', 'A really interesting way of adding interest but let down a little by the weather - the sky is just too overcast to provide either the warmer lighting that would bring this alive or the interesting backdrop the would provide more colour.', '2004-04-26 16:00:43.000000', NULL, 1),
(686093, 71361, 327, '<td valign="top">Lovely....what is not to like? I think this is super with good colors and nice composition.</td>', 'Lovely....what is not to like? I think this is super with good colors and nice composition.', '2004-04-26 16:00:46.000000', NULL, 1),
(686095, 72119, 3087, '<td valign="top">The depth of colour in the clouds, reflected too in the sea, really adds impact to this image and the composition works well too.</td>', 'The depth of colour in the clouds, reflected too in the sea, really adds impact to this image and the composition works well too.', '2004-04-26 16:01:41.000000', NULL, 1),
(686097, 72230, 3087, '<td valign="top">A lovely image with a wonderful desolate air to it. Despite the subject matter I think I''d prefer a touch more contrast.</td>', 'A lovely image with a wonderful desolate air to it. Despite the subject matter I think I''d prefer a touch more contrast.', '2004-04-26 16:02:28.000000', NULL, 1),
(686099, 71957, 3087, '<td valign="top">Lighting is great and I love the high contrast. Composition is great with the two trees, diagonal line of the fence and wonderfully ornate bandstand. A great image!<br/> <br/>Edit to correct typos!<br/><br/><i>Message edited by author 2004-05-04 08:46:07.</i></td>', 'Lighting is great and I love the high contrast. Composition is great with the two trees, diagonal line of the fence and wonderfully ornate bandstand. A great image! Edit to correct typos!', '2004-04-26 16:03:30.000000', '2004-05-04 09:46:07.000000', 1),
(686100, 72336, 3087, '<td valign="top">What wonderful use of repetition and of light and shadow. The image has a slightly surreal air to it... excellent!</td>', 'What wonderful use of repetition and of light and shadow. The image has a slightly surreal air to it... excellent!', '2004-04-26 16:04:17.000000', NULL, 1),
(686102, 71761, 3087, '<td valign="top">Great low viewpoint - would love an additional point of foreground interest such as a larger pebble jutting out of the water or a piece of driftwood against the rich colours of the pebbles beneath.</td>', 'Great low viewpoint - would love an additional point of foreground interest such as a larger pebble jutting out of the water or a piece of driftwood against the rich colours of the pebbles beneath.', '2004-04-26 16:05:21.000000', NULL, 1),
(686103, 72330, 327, '<td valign="top">Nice view of a great American city.  My husband was a lifeguard at Oak Street Beach....long ago. :) Good dof, focus and colors. Good luck in the challenge.</td>', 'Nice view of a great American city.  My husband was a lifeguard at Oak Street Beach....long ago. :) Good dof, focus and colors. Good luck in the challenge.', '2004-04-26 16:05:33.000000', NULL, 1),
(686104, 72169, 3087, '<td valign="top">Lovely use of the curved path to lead into the background and provide interest. Black and white works very well for this image.</td>', 'Lovely use of the curved path to lead into the background and provide interest. Black and white works very well for this image.', '2004-04-26 16:05:57.000000', NULL, 1),
(686105, 72232, 3087, '<td valign="top">Love the concentration on foreground and the very low viewpoint - really puts the focus on the surroundings rather than the town. Composition works very well.</td>', 'Love the concentration on foreground and the very low viewpoint - really puts the focus on the surroundings rather than the town. Composition works very well.', '2004-04-26 16:07:01.000000', NULL, 1),
(686107, 72085, 3087, '<td valign="top">Nice mix of fore-, mid- and background interest. Nice composition with left foreground rock balancing right of centre midground rock. Lovely colours too and the gull adds just the right touch of detail.</td>', 'Nice mix of fore-, mid- and background interest. Nice composition with left foreground rock balancing right of centre midground rock. Lovely colours too and the gull adds just the right touch of detail.', '2004-04-26 16:07:58.000000', NULL, 1),
(686108, 72095, 3087, '<td valign="top">Lighting feels a little flat - would prefer the more golden light of early morning or late afternoon. Great foreground interest - I like the horizontal lines of water, waterbreak, water and then the city. Also like the way the people are on the same side as the tall tower - just seems to balance well.</td>', 'Lighting feels a little flat - would prefer the more golden light of early morning or late afternoon. Great foreground interest - I like the horizontal lines of water, waterbreak, water and then the city. Also like the way the people are on the same side as the tall tower - just seems to balance well.', '2004-04-26 16:09:30.000000', NULL, 1),
(686121, 72001, 11895, '<td valign="top">I think you''ve got too much in this shot making it seem busy, maybe composing it in a way that left the guard rail out of the foreground would work better, colors are good</td>', 'I think you''ve got too much in this shot making it seem busy, maybe composing it in a way that left the guard rail out of the foreground would work better, colors are good', '2004-04-26 16:16:20.000000', NULL, 1),
(686127, 72310, 11895, '<td valign="top">I don''t like that half of his face is shaded</td>', 'I don''t like that half of his face is shaded', '2004-04-26 16:18:37.000000', NULL, 1),
(686136, 72245, 11895, '<td valign="top">the darkness from the right side overpowers the far better elements shown in the lighter portion</td>', 'the darkness from the right side overpowers the far better elements shown in the lighter portion', '2004-04-26 16:28:29.000000', NULL, 1),
(686139, 72288, 3102, '<td valign="top">Heh... looks like she''s about to snag a bird!  My dad did that once in Florida -- he snagged a pelican.  We joked that he was "fly fishing."</td>', 'Heh... looks like she''s about to snag a bird!  My dad did that once in Florida -- he snagged a pelican.  We joked that he was "fly fishing."', '2004-04-26 16:30:37.000000', NULL, 1),
(686140, 72331, 5391, '<td valign="top">An excellent shot, but I''m not sure it fits well with "where you live", being a boat and all.  The title helps, but it''s a stretch.</td>', 'An excellent shot, but I''m not sure it fits well with "where you live", being a boat and all.  The title helps, but it''s a stretch.', '2004-04-26 16:30:52.000000', NULL, 1),
(686141, 72248, 11895, '<td valign="top">I wish there was more color in the sky, it bleeds into the top of the shell, very nice DoF</td>', 'I wish there was more color in the sky, it bleeds into the top of the shell, very nice DoF', '2004-04-26 16:30:56.000000', NULL, 1),
(686142, 71883, 3102, '<td valign="top">Beautiful!  I''m jealous :)</td>', 'Beautiful!  I''m jealous :)', '2004-04-26 16:31:17.000000', NULL, 1),
(686143, 72245, 5391, '<td valign="top">The nighttime exposure is done very well, but I don''t care for the darker areas at the right side or the bottom of the frame.  They make the whole thing feel a bit out of balance to me.</td>', 'The nighttime exposure is done very well, but I don''t care for the darker areas at the right side or the bottom of the frame.  They make the whole thing feel a bit out of balance to me.', '2004-04-26 16:31:48.000000', NULL, 1),
(686144, 72247, 4517, '<td valign="top">Wow great view. 9</td>', 'Wow great view. 9', '2004-04-26 16:32:04.000000', NULL, 1),
(686146, 72253, 3102, '<td valign="top">Beautiful scene!</td>', 'Beautiful scene!', '2004-04-26 16:32:35.000000', NULL, 1),
(686147, 72138, 3102, '<td valign="top">It''s a bummer that the sky is rather blown out -- otherwise it''s an awesome scene!</td>', 'It''s a bummer that the sky is rather blown out -- otherwise it''s an awesome scene!', '2004-04-26 16:33:21.000000', NULL, 1),
