(686409, 72278, 3607, '<td valign="top">the blues and shadows look great.  perhaps less buildings on the right and sky and more ocean would have made it a more powerful photo.</td>', 'the blues and shadows look great.  perhaps less buildings on the right and sky and more ocean would have made it a more powerful photo.', '2004-04-26 20:21:26.000000', NULL, 1),
(686410, 71124, 3607, '<td valign="top">great water reflecting night shot.  well done!</td>', 'great water reflecting night shot.  well done!', '2004-04-26 20:21:56.000000', NULL, 1),
