(686516, 71935, 13897, '<td valign="top">I''ve walked around this lake many times. Great shot here as far as POV. How would it have worked with the trunk of the tree on the right showing? Or, the tree on the left not showing? Nice work.</td>', 'I''ve walked around this lake many times. Great shot here as far as POV. How would it have worked with the trunk of the tree on the right showing? Or, the tree on the left not showing? Nice work.', '2004-04-26 21:21:30.000000', NULL, 1),
(686517, 72001, 19608, '<td valign="top">Composition works nicely - except for the guard rail at the bottom left.  Colors seem a bit over saturated - but work well together.</td>', 'Composition works nicely - except for the guard rail at the bottom left.  Colors seem a bit over saturated - but work well together.', '2004-04-26 21:21:42.000000', NULL, 1),
(686518, 72042, 6999, '<td valign="top">I think I''d personally have coloured it all in, rather than leaving the land in monochrome. There is some appeal for me in the effect, probably especially in the shade of red you''ve chosen ... but perhaps (and I''m searching for the right words to express my feelings about it here) it''s rather more about the effect than the photograph.</td>', 'I think I''d personally have coloured it all in, rather than leaving the land in monochrome. There is some appeal for me in the effect, probably especially in the shade of red you''ve chosen ... but perhaps (and I''m searching for the right words to express my feelings about it here) it''s rather more about the effect than the photograph.', '2004-04-26 21:21:46.000000', NULL, 1),
(686519, 72262, 16386, '<td valign="top">good angle.</td>', 'good angle.', '2004-04-26 21:22:14.000000', NULL, 1),
(686520, 72256, 19608, '<td valign="top">Interesting composition.  Image has good strong blacks and some nice crisp whites.</td>', 'Interesting composition.  Image has good strong blacks and some nice crisp whites.', '2004-04-26 21:23:10.000000', NULL, 1),
(686521, 72230, 16386, '<td valign="top">....deserted country?</td>', '....deserted country?', '2004-04-26 21:23:24.000000', NULL, 1),
(686523, 72254, 19608, '<td valign="top">Looks like a great place to live.  The bird is a great touch.  The boats on the left side of the dock detract for me.  The rainy weather does not allow much excitement in the sky.</td>', 'Looks like a great place to live.  The bird is a great touch.  The boats on the left side of the dock detract for me.  The rainy weather does not allow much excitement in the sky.', '2004-04-26 21:25:29.000000', NULL, 1),
(686525, 72227, 19608, '<td valign="top">Nice composition - perfect use of the S curve.  The soft muted colors work extremely well in this image.  I would have given you more points if the S curve had a person at the end. (Maybe in a red coat :)  )</td>', 'Nice composition - perfect use of the S curve.  The soft muted colors work extremely well in this image.  I would have given you more points if the S curve had a person at the end. (Maybe in a red coat :)  )', '2004-04-26 21:27:22.000000', NULL, 1),
(686526, 72051, 19608, '<td valign="top">Nice lighting - a tranquil scene.  Colors are perfectly exposed.</td>', 'Nice lighting - a tranquil scene.  Colors are perfectly exposed.', '2004-04-26 21:28:15.000000', NULL, 1),
(686528, 72260, 19608, '<td valign="top">A nice moody picture, lots of interest.</td>', 'A nice moody picture, lots of interest.', '2004-04-26 21:28:57.000000', NULL, 1),
(686530, 71634, 19608, '<td valign="top">Nice angle. Good lighting and exposure.  Looks like the home plate umps right arm is extended, but the btter hasn''t swung yet.</td>', 'Nice angle. Good lighting and exposure.  Looks like the home plate umps right arm is extended, but the btter hasn''t swung yet.', '2004-04-26 21:30:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(686532, 72289, 19608, '<td valign="top">Nice muted colors.  Diagonal shoreline at bottom is effective.</td>', 'Nice muted colors.  Diagonal shoreline at bottom is effective.', '2004-04-26 21:31:42.000000', NULL, 1),
(686533, 72085, 327, '<td valign="top">Zoomdak? my guess this is yours. It a cool shot, and the colors are rich and interesting. Good going.</td>', 'Zoomdak? my guess this is yours. It a cool shot, and the colors are rich and interesting. Good going.', '2004-04-26 21:31:44.000000', NULL, 1),
(686534, 72259, 19608, '<td valign="top">Is that a cemetery behind?  If so - what a welcome.  Colors are nice except the bald white sky detracts.</td>', 'Is that a cemetery behind?  If so - what a welcome.  Colors are nice except the bald white sky detracts.', '2004-04-26 21:32:41.000000', NULL, 1),
(686535, 72325, 19608, '<td valign="top">Very nice peaceful image.  Relaxing.  I would have rated it another point higher if the sky were not quite so bright.</td>', 'Very nice peaceful image.  Relaxing.  I would have rated it another point higher if the sky were not quite so bright.', '2004-04-26 21:33:38.000000', NULL, 1),
(686536, 72085, 19608, '<td valign="top">Nice composition.  The layering effect of the background hills add lots of depth.  Bird a nice touch.</td>', 'Nice composition.  The layering effect of the background hills add lots of depth.  Bird a nice touch.', '2004-04-26 21:34:43.000000', NULL, 1),
(686540, 71124, 19608, '<td valign="top">Wonderful reflection shot at just the right time of day (night.)  The last vestages of blue in the sky make it really pop.</td>', 'Wonderful reflection shot at just the right time of day (night.)  The last vestages of blue in the sky make it really pop.', '2004-04-26 21:35:48.000000', NULL, 1),
(686546, 72055, 19608, '<td valign="top">Great colors - the rainbow adds a great touch.  The receding shoreline make you think the horizon isn''t straight - but it also looks like the building slopes down to the left.  Great composition to get the entire water spout.</td>', 'Great colors - the rainbow adds a great touch.  The receding shoreline make you think the horizon isn''t straight - but it also looks like the building slopes down to the left.  Great composition to get the entire water spout.', '2004-04-26 21:37:36.000000', NULL, 1),
(686550, 71201, 19608, '<td valign="top">The colors really pop.  The bicycle rider adds a lot - and is well placed.  My biggest concern is that the horizon isn''t straight - all the buildings lean to the left.</td>', 'The colors really pop.  The bicycle rider adds a lot - and is well placed.  My biggest concern is that the horizon isn''t straight - all the buildings lean to the left.', '2004-04-26 21:38:58.000000', NULL, 1),
(686553, 71897, 19608, '<td valign="top">Interesting composition - the diagonal blue area leads in from the bottom left right to the tower.  But, there''s probably too much foilage and not enough of the building.</td>', 'Interesting composition - the diagonal blue area leads in from the bottom left right to the tower.  But, there''s probably too much foilage and not enough of the building.', '2004-04-26 21:40:46.000000', NULL, 1),
(686556, 71957, 20102, '<td valign="top">If only I could vote... Great job, good luck.</td>', 'If only I could vote... Great job, good luck.', '2004-04-26 21:43:43.000000', NULL, 1),
(686557, 71957, 5391, '<td valign="top">Stunning shot.  Just beautiful tonal range, here.  Great composition, everything.  9</td>', 'Stunning shot.  Just beautiful tonal range, here.  Great composition, everything.  9', '2004-04-26 21:43:58.000000', NULL, 1),
(686561, 72208, 19608, '<td valign="top">Very interesting spot.  I LOVE the bottom half - the bricks and the orange, gray and green work well together. Then there''s the top where the garish colors clash so bad!  Nicely exposed (and that was tough I''m sure) and seems very sharp throughout.</td>', 'Very interesting spot.  I LOVE the bottom half - the bricks and the orange, gray and green work well together. Then there''s the top where the garish colors clash so bad!  Nicely exposed (and that was tough I''m sure) and seems very sharp throughout.', '2004-04-26 21:46:22.000000', NULL, 1),
(686562, 72144, 5391, '<td valign="top">Wow - that''s just incredible.  Beautiful shot, one of my favorites so far in the challenge.</td>', 'Wow - that''s just incredible.  Beautiful shot, one of my favorites so far in the challenge.', '2004-04-26 21:47:39.000000', NULL, 1),
(686563, 71588, 19608, '<td valign="top">Nice seeing.  The sky is so clear and the water so calm - it''s a peaceful scene.  With all the blue - the small amouts of yellow and red really pop.</td>', 'Nice seeing.  The sky is so clear and the water so calm - it''s a peaceful scene.  With all the blue - the small amouts of yellow and red really pop.', '2004-04-26 21:47:58.000000', NULL, 1),
(686564, 71939, 5391, '<td valign="top">The top lights that form stars are of interest, but the bottom splotch of overexposure just makes me feel like I''m being blinded.  If it weren''t for that, this would be a fantastic shot.</td>', 'The top lights that form stars are of interest, but the bottom splotch of overexposure just makes me feel like I''m being blinded.  If it weren''t for that, this would be a fantastic shot.', '2004-04-26 21:48:42.000000', NULL, 1),
(686568, 71939, 19608, '<td valign="top">Very interesting shot.  Ghostly trees are super as are the star lights.  The white "blob" at the bottom is unfortunate.</td>', 'Very interesting shot.  Ghostly trees are super as are the star lights.  The white "blob" at the bottom is unfortunate.', '2004-04-26 21:49:24.000000', NULL, 1),
(686575, 72001, 5391, '<td valign="top">The colors in this shot seem a bit surreal - I think it must be the blue color of the sky.  A bit too much contrast, maybe.</td>', 'The colors in this shot seem a bit surreal - I think it must be the blue color of the sky.  A bit too much contrast, maybe.', '2004-04-26 22:06:40.000000', NULL, 1),
