(686661, 72033, 19608, '<td valign="top">Nice silhouette - and great colors.  Sun a bit hot but not enough to subtract points.</td>', 'Nice silhouette - and great colors.  Sun a bit hot but not enough to subtract points.', '2004-04-26 23:05:02.000000', NULL, 1),
