(686978, 72121, 18080, '<td valign="top">Love the title.<br/>This is a well taken, crisp, clean shot. Should do well.</td>', 'Love the title.This is a well taken, crisp, clean shot. Should do well.', '2004-04-27 05:04:27.000000', NULL, 1),
(686980, 72264, 16004, '<td valign="top">Goodness - great timing here!  I like this shot - pretty moody and pretty pretty too!  Your choice of cropping might have been improved a little, methinks, such as cutting off the bottom from the base of the trees...  And though I do like the big glowy ball thing, I think it diverts / competes for attention from the lightning ; chopping out the top of the tower would leave an awkward looking column but it might be worth it.  dunno, would be an awkward call, that...  The flow of the picture might be better if it were displayed in landscape, rather than portrait.  I''d also be tempted to play with a bit of an increase in contrast in the sky - darkening the sky and making the lightning more prominent... I totally love the blackness of the office buildings though, and they very definitely add to the overall feel of the picture.  7.</td>', 'Goodness - great timing here!  I like this shot - pretty moody and pretty pretty too!  Your choice of cropping might have been improved a little, methinks, such as cutting off the bottom from the base of the trees...  And though I do like the big glowy ball thing, I think it diverts / competes for attention from the lightning ; chopping out the top of the tower would leave an awkward looking column but it might be worth it.  dunno, would be an awkward call, that...  The flow of the picture might be better if it were displayed in landscape, rather than portrait.  I''d also be tempted to play with a bit of an increase in contrast in the sky - darkening the sky and making the lightning more prominent... I totally love the blackness of the office buildings though, and they very definitely add to the overall feel of the picture.  7.', '2004-04-27 05:07:06.000000', NULL, 1),
(686986, 72115, 10883, '<td valign="top">Nice wide angle, I would like to have seen it level, not tilted.. The tilted angle does not work for me.</td>', 'Nice wide angle, I would like to have seen it level, not tilted.. The tilted angle does not work for me.', '2004-04-27 05:10:59.000000', NULL, 1),
(686989, 72037, 10883, '<td valign="top">Very good capture, nice motion blur in the back.</td>', 'Very good capture, nice motion blur in the back.', '2004-04-27 05:12:22.000000', NULL, 1),
