(687332, 72122, 18709, '<td valign="top">A strange distorted shot, of a multi-storey car park , I presume.   Well-done though.  The sky is very dark through the extra layers of glass.</td>', 'A strange distorted shot, of a multi-storey car park , I presume.   Well-done though.  The sky is very dark through the extra layers of glass.', '2004-04-27 12:30:43.000000', NULL, 1),
(687333, 71911, 18709, '<td valign="top">You can''t get more characteristic than this.  It looks like everybody''s town.<br/></td>', 'You can''t get more characteristic than this.  It looks like everybody''s town.', '2004-04-27 12:32:14.000000', NULL, 1),
(687334, 72281, 1202, '<td valign="top">Composition: Subject Placement, Cropping, Background	7	<br/>Technical: Focus, Exposure, Lighting, Processing	10	<br/>Appeal: Is it Interesting, Motivating, Etc.? 	6	<br/>How well it meets the challenge:	10	<br/>Total Averaged Rating	8	   Dick<br/></td>', 'Composition: Subject Placement, Cropping, Background	7	Technical: Focus, Exposure, Lighting, Processing	10	Appeal: Is it Interesting, Motivating, Etc.? 	6	How well it meets the challenge:	10	Total Averaged Rating	8	   Dick', '2004-04-27 12:32:27.000000', NULL, 1),
