(687797, 71957, 19608, '<td valign="top">Very nice composition and rendering.  It is clean and crisp with great tonal range.  On my second pass through my scores - I added a point.</td>', 'Very nice composition and rendering.  It is clean and crisp with great tonal range.  On my second pass through my scores - I added a point.', '2004-04-27 18:15:33.000000', NULL, 1),
(687800, 72331, 19608, '<td valign="top">Nice action and colors.  Water holds detail very well.  Sailboats in front are a great touch.</td>', 'Nice action and colors.  Water holds detail very well.  Sailboats in front are a great touch.', '2004-04-27 18:16:41.000000', NULL, 1),
(687802, 72223, 19608, '<td valign="top">Nice lighting and composition.  Would have had a bit more interest if a jogger/walker were on the path - but that''s a very minor point.</td>', 'Nice lighting and composition.  Would have had a bit more interest if a jogger/walker were on the path - but that''s a very minor point.', '2004-04-27 18:18:03.000000', NULL, 1),
(687806, 72223, 18709, '<td valign="top">Really good clean shot. Perfectly placed.</td>', 'Really good clean shot. Perfectly placed.', '2004-04-27 18:18:39.000000', NULL, 1),
(687807, 71940, 19608, '<td valign="top">Great lighting - nice composition.  Would have been better if there were more light on the people though.  Very well done.</td>', 'Great lighting - nice composition.  Would have been better if there were more light on the people though.  Very well done.', '2004-04-27 18:19:04.000000', NULL, 1),
(687808, 71240, 19608, '<td valign="top">Ohmygosh - and it''s 95 degrees outside right now.  Nice fairly land image - well composed and rendered.</td>', 'Ohmygosh - and it''s 95 degrees outside right now.  Nice fairly land image - well composed and rendered.', '2004-04-27 18:20:22.000000', NULL, 1),
(687810, 72087, 19608, '<td valign="top">This image  has a nice comfortable feel to it.  Very good reflection.  Sky a bit boring but the clouds help somewhat.</td>', 'This image  has a nice comfortable feel to it.  Very good reflection.  Sky a bit boring but the clouds help somewhat.', '2004-04-27 18:21:46.000000', NULL, 1),
(687813, 72338, 19608, '<td valign="top">Nice touch to use the blue to stand out.</td>', 'Nice touch to use the blue to stand out.', '2004-04-27 18:22:50.000000', NULL, 1),
