(688867, 71123, 13381, '<td valign="top">I really like the use of negative space here.  The sky seems to go on forever.</td>', 'I really like the use of negative space here.  The sky seems to go on forever.', '2004-04-28 11:00:06.000000', NULL, 1),
(688892, 72155, 15920, '<td valign="top">Too small to really appreciate.</td>', 'Too small to really appreciate.', '2004-04-28 11:14:04.000000', NULL, 1),
(688932, 72068, 4008, '<td valign="top">Great shot with great light. The audience, the field and then the city behind it. It creates a real atmosphere of an exciting big city, Very fitting to the challenge. Inclusion of the name sign on the left would have been perfect. In my top 3</td>', 'Great shot with great light. The audience, the field and then the city behind it. It creates a real atmosphere of an exciting big city, Very fitting to the challenge. Inclusion of the name sign on the left would have been perfect. In my top 3', '2004-04-28 11:33:23.000000', NULL, 1),
(688934, 72085, 4008, '<td valign="top">Lovely image, I love the haze and the different green and blue colors. Strong composition. I like the inclusion of the seagull, although my eye is jumping from the seagull to the rock on the right and back, but it makes the image more interesting. In my top 3.</td>', 'Lovely image, I love the haze and the different green and blue colors. Strong composition. I like the inclusion of the seagull, although my eye is jumping from the seagull to the rock on the right and back, but it makes the image more interesting. In my top 3.', '2004-04-28 11:33:46.000000', NULL, 1),
(689065, 72055, 20887, '<td valign="top">It looks like the water shooting up and blowing away in combination with the rainbow forms a sail... an oversized, translucent sail...</td>', 'It looks like the water shooting up and blowing away in combination with the rainbow forms a sail... an oversized, translucent sail...', '2004-04-28 13:02:34.000000', NULL, 1),
(689081, 72109, 20887, '<td valign="top">I love how you have the photo cut almost exactly in half... one side simple angles, the other side simple blue... not even a single cloud to throw off the balance.</td>', 'I love how you have the photo cut almost exactly in half... one side simple angles, the other side simple blue... not even a single cloud to throw off the balance.', '2004-04-28 13:15:21.000000', NULL, 1),
(689096, 71976, 16636, '<td valign="top">There''s something that just does not look real with this photo?</td>', 'There''s something that just does not look real with this photo?', '2004-04-28 13:26:34.000000', NULL, 1),
(689105, 72068, 16636, '<td valign="top">what a stunning image, the light was perfect and exposure is spot on - well done, should do well</td>', 'what a stunning image, the light was perfect and exposure is spot on - well done, should do well', '2004-04-28 13:42:45.000000', NULL, 1),
(689118, 72242, 13044, '<td valign="top">Nice composition, but a bit overexposed in the fore ground.</td>', 'Nice composition, but a bit overexposed in the fore ground.', '2004-04-28 13:49:27.000000', NULL, 1),
(689138, 71588, 16636, '<td valign="top">Beautiful!!!</td>', 'Beautiful!!!', '2004-04-28 13:57:30.000000', NULL, 1),
(689194, 71927, 15920, '<td valign="top">Well done.  Lighting on the fountain, bold hats, flowers in the foreground are all strong.  I might have traded a shorter shutter speed and the less smooth water that goes with it for some additional sharpness on the people which is generally lost with the longer shutter speeds, but that is a nit pick.  This is a very nice shot. -9</td>', 'Well done.  Lighting on the fountain, bold hats, flowers in the foreground are all strong.  I might have traded a shorter shutter speed and the less smooth water that goes with it for some additional sharpness on the people which is generally lost with the longer shutter speeds, but that is a nit pick.  This is a very nice shot. -9', '2004-04-28 14:22:25.000000', NULL, 1),
(689297, 71715, 17033, '<td valign="top">tilt very noticeable on silos</td>', 'tilt very noticeable on silos', '2004-04-28 15:48:29.000000', NULL, 1),
(689304, 72096, 16777, '<td valign="top">Seems a bit flat.</td>', 'Seems a bit flat.', '2004-04-28 15:52:23.000000', NULL, 1),
