(689312, 71361, 16777, '<td valign="top">Without anything else in the foreground the tree seems to be more of a distraction rather than a framing element.</td>', 'Without anything else in the foreground the tree seems to be more of a distraction rather than a framing element.', '2004-04-28 15:58:47.000000', NULL, 1),
(689321, 71976, 17033, '<td valign="top">Argyll? Nice shot but there''s something not quite right with the angle....house is a little off and the loch behind seems to rising up the slope.</td>', 'Argyll? Nice shot but there''s something not quite right with the angle....house is a little off and the loch behind seems to rising up the slope.', '2004-04-28 16:05:25.000000', NULL, 1),
