(689406, 72166, 17033, '<td valign="top">Ramp a little too central, perhaps. Nice light/haze on mountains, though.</td>', 'Ramp a little too central, perhaps. Nice light/haze on mountains, though.', '2004-04-28 16:58:46.000000', NULL, 1),
(689413, 71883, 17033, '<td valign="top">Perhaps this would have been more striking if closest bit of land (bit dull) had been cropped out....or pic taken in a position to include more water there.</td>', 'Perhaps this would have been more striking if closest bit of land (bit dull) had been cropped out....or pic taken in a position to include more water there.', '2004-04-28 17:00:54.000000', NULL, 1),
