(689619, 72327, 16499, '<td valign="top">Is that a cloud shadow in the center? Pity...</td>', 'Is that a cloud shadow in the center? Pity...', '2004-04-28 18:52:00.000000', NULL, 1),
(689624, 71361, 16499, '<td valign="top">Water and sky are of strange color. I''d say it''s an autumn storm coming. Was it really like that or some funny processing?</td>', 'Water and sky are of strange color. I''d say it''s an autumn storm coming. Was it really like that or some funny processing?', '2004-04-28 18:54:35.000000', NULL, 1),
(689627, 72245, 16499, '<td valign="top">Very unusual light, I like it ;-)</td>', 'Very unusual light, I like it ;-)', '2004-04-28 18:55:59.000000', NULL, 1),
(689628, 72256, 16499, '<td valign="top">I am unsure that this one benefits from BW...</td>', 'I am unsure that this one benefits from BW...', '2004-04-28 18:56:40.000000', NULL, 1),
(689635, 72109, 16499, '<td valign="top">Pity that the tree is not sharp...</td>', 'Pity that the tree is not sharp...', '2004-04-28 19:01:00.000000', NULL, 1),
(689653, 72260, 13035, '<td valign="top">My choice for best of show.  While it''s difficult to critique truly wonderful photos, here goes.   There are four things to clone out.  Everything about this image is soft and mysterious.  The rock at the far point, where the water meets the land catches my eye.  Like wise the same with a tube or a person positioned to the far left of the dock, as well as the two rocks or supports that interupt the curve on the underside arch of the dock.  The  device on top of the tallest bridge support looks very modern and out of flavor for the rest of the image.  I would remove that also.   Finally, I would love to see this in sepia.  An absolutly great, great shot.  Good luch!!  10</td>', 'My choice for best of show.  While it''s difficult to critique truly wonderful photos, here goes.   There are four things to clone out.  Everything about this image is soft and mysterious.  The rock at the far point, where the water meets the land catches my eye.  Like wise the same with a tube or a person positioned to the far left of the dock, as well as the two rocks or supports that interupt the curve on the underside arch of the dock.  The  device on top of the tallest bridge support looks very modern and out of flavor for the rest of the image.  I would remove that also.   Finally, I would love to see this in sepia.  An absolutly great, great shot.  Good luch!!  10', '2004-04-28 19:12:39.000000', NULL, 1),
(689678, 72155, 18403, '<td valign="top">Just make it larger!</td>', 'Just make it larger!', '2004-04-28 19:32:16.000000', NULL, 1),
(689719, 71717, 11248, '<td valign="top">I like much.: The beauty of the scene. The blue of the lake. I would live there.<br/>I like less: -<br/>scrore: 9</td>', 'I like much.: The beauty of the scene. The blue of the lake. I would live there.I like less: -scrore: 9', '2004-04-28 20:10:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(689722, 72336, 11248, '<td valign="top">I like much:  The lighting. - The angles. - The contrast between blue and orange.<br/>I like less: -<br/>Score: 9</td>', 'I like much:  The lighting. - The angles. - The contrast between blue and orange.I like less: -Score: 9', '2004-04-28 20:11:23.000000', NULL, 1),
(689725, 72139, 11248, '<td valign="top">I like much: The simplicity of the shot. - The desaturated backgournd.<br/>I like less: the way you fited it to the challenge theme.<br/>Score: 9</td>', 'I like much: The simplicity of the shot. - The desaturated backgournd.I like less: the way you fited it to the challenge theme.Score: 9', '2004-04-28 20:12:21.000000', NULL, 1),
(689730, 71935, 11248, '<td valign="top">I like much: The beautiful colors of tulips illuminating a grey sky day.<br/>I like less: -<br/>Score: 9</td>', 'I like much: The beautiful colors of tulips illuminating a grey sky day.I like less: -Score: 9', '2004-04-28 20:14:05.000000', NULL, 1),
(689733, 72126, 11248, '<td valign="top">I like much: The solitude of house - The simplicity of the scene.<br/>I like less: The dull colors.<br/>Score: 8</td>', 'I like much: The solitude of house - The simplicity of the scene.I like less: The dull colors.Score: 8', '2004-04-28 20:15:03.000000', NULL, 1),
(689735, 72002, 13035, '<td valign="top">What a great shot.  Speaking strictly as the guide book editor, I would request the following post processing.  Clone the little flags (or whatever they are) off the top of all the masts.  Where a mast protrudes into the skyline, and it can''t really be linked to what boat it is from, remove it.  Where a mast cuts a major building in the horizon in half, remove it.  There.  Now you can be on the cover!  Nice, nice work.  Good luck!! 9</td>', 'What a great shot.  Speaking strictly as the guide book editor, I would request the following post processing.  Clone the little flags (or whatever they are) off the top of all the masts.  Where a mast protrudes into the skyline, and it can''t really be linked to what boat it is from, remove it.  Where a mast cuts a major building in the horizon in half, remove it.  There.  Now you can be on the cover!  Nice, nice work.  Good luck!! 9', '2004-04-28 20:15:38.000000', NULL, 1),
