(692433, 71993, 11769, '<td valign="top">Countrified I say. Nice light.</td>', 'Countrified I say. Nice light.', '2004-05-01 01:30:23.000000', NULL, 1),
(692497, 72119, 4767, '<td valign="top">You gotta love spring weather in your neighborhood, eh?</td>', 'You gotta love spring weather in your neighborhood, eh?', '2004-05-01 02:44:09.000000', NULL, 1),
(692505, 72120, 6104, '<td valign="top">amazing clouds</td>', 'amazing clouds', '2004-05-01 03:21:38.000000', NULL, 1),
(692511, 72279, 6477, '<td valign="top">The colors work perfect for my taste, as well as the shadows, tones and composition. Beautiful image. Good luck</td>', 'The colors work perfect for my taste, as well as the shadows, tones and composition. Beautiful image. Good luck', '2004-05-01 03:47:16.000000', NULL, 1),
(692549, 72260, 17551, '<td valign="top">Black &amp; white is a great choice here, super shot</td>', 'Black & white is a great choice here, super shot', '2004-05-01 06:23:37.000000', NULL, 1),
