INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(692756, 71732, 18709, '<td valign="top">A very impressive piece of engineering.  Well taken.</td>', 'A very impressive piece of engineering.  Well taken.', '2004-05-01 14:43:01.000000', NULL, 1),
