(693691, 72272, 14986, '<td valign="top">Pretty shot.  Too bad the tower seems tilted to me.</td>', 'Pretty shot.  Too bad the tower seems tilted to me.', '2004-05-02 15:22:53.000000', NULL, 1),
(693692, 72247, 14986, '<td valign="top">If taken from a plane...your planes have cleaner windows than the ones I''ve been on!   This is a really nice shot.   The shoreline really adds interest.</td>', 'If taken from a plane...your planes have cleaner windows than the ones I''ve been on!   This is a really nice shot.   The shoreline really adds interest.', '2004-05-02 15:24:20.000000', NULL, 1),
(693695, 72331, 14986, '<td valign="top">I predict a ribbon for this one!   Great clarity and interest in this shot.  The sun is at a perfect angle for you, and the rocking of the boat makes the viewer feel as if we''re right there behind it.  Great shot!</td>', 'I predict a ribbon for this one!   Great clarity and interest in this shot.  The sun is at a perfect angle for you, and the rocking of the boat makes the viewer feel as if we''re right there behind it.  Great shot!', '2004-05-02 15:26:20.000000', NULL, 1),
(693696, 72169, 20539, '<td valign="top">a little dark, but still beautifull  -9</td>', 'a little dark, but still beautifull  -9', '2004-05-02 15:26:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(693698, 71482, 14986, '<td valign="top">Very pretty shot.  Nice to see someplace without skyscrapers and billboards that still exsists!</td>', 'Very pretty shot.  Nice to see someplace without skyscrapers and billboards that still exsists!', '2004-05-02 15:27:04.000000', NULL, 1),
(693700, 72002, 20539, '<td valign="top">very nicely shot. well done -10</td>', 'very nicely shot. well done -10', '2004-05-02 15:27:58.000000', NULL, 1),
(693702, 71571, 20539, '<td valign="top">out of context</td>', 'out of context', '2004-05-02 15:28:55.000000', NULL, 1),
(693704, 71902, 14986, '<td valign="top">Very nice composition.  I really like the yellow building at the end of the path.   Only thing I would do differently, is I think I would warm up the tone of the photo just a bit.  It seems to have a slight bueish cast to it.  I might also rotate it just slightly counter clockwise.   I like it, though!</td>', 'Very nice composition.  I really like the yellow building at the end of the path.   Only thing I would do differently, is I think I would warm up the tone of the photo just a bit.  It seems to have a slight bueish cast to it.  I might also rotate it just slightly counter clockwise.   I like it, though!', '2004-05-02 15:29:13.000000', NULL, 1),
(693741, 71935, 4321, '<td valign="top">Wow...the tulips just pop right out, great color</td>', 'Wow...the tulips just pop right out, great color', '2004-05-02 16:29:03.000000', NULL, 1),
(693747, 72085, 4321, '<td valign="top">Different than the usual Haystack Rock picture....lovely</td>', 'Different than the usual Haystack Rock picture....lovely', '2004-05-02 16:34:22.000000', NULL, 1),
(693748, 72085, 10869, '<td valign="top">Great colors</td>', 'Great colors', '2004-05-02 16:34:51.000000', NULL, 1),
(693750, 71634, 4321, '<td valign="top">Love this! My husband and son say I have to give you a 10!!</td>', 'Love this! My husband and son say I have to give you a 10!!', '2004-05-02 16:41:32.000000', NULL, 1),
(693757, 71993, 9668, '<td valign="top">The border seems a little bit overpowering. Interesting DOF, I like how sharp the church and town are, yet don''t seem oversharpened. Nice composition.</td>', 'The border seems a little bit overpowering. Interesting DOF, I like how sharp the church and town are, yet don''t seem oversharpened. Nice composition.', '2004-05-02 16:50:18.000000', NULL, 1),
(693758, 72234, 1031, '<td valign="top">I''m not used to seeing those willows with that light/bright a color (early growth?), so it looks a little odd that way. Lovely pastoral setting, I find willows very photogenic. Good decision to fill the sky with the branches, but I think I''d take away the evidence of the shoreline from the lower-left by trimming a tiny bit from the laft and bottom.</td>', 'I''m not used to seeing those willows with that light/bright a color (early growth?), so it looks a little odd that way. Lovely pastoral setting, I find willows very photogenic. Good decision to fill the sky with the branches, but I think I''d take away the evidence of the shoreline from the lower-left by trimming a tiny bit from the laft and bottom.', '2004-05-02 16:51:00.000000', NULL, 1),
(693762, 71897, 9668, '<td valign="top">This image seems a little bit dull. I like how the steeple is peeking out from behind the trees.</td>', 'This image seems a little bit dull. I like how the steeple is peeking out from behind the trees.', '2004-05-02 16:55:09.000000', NULL, 1),
(693763, 72011, 9668, '<td valign="top">Nice panoramic. The trees infront seem unnaturally blurred. Nice contrast in b&amp;w. Beautiful mountainscape.</td>', 'Nice panoramic. The trees infront seem unnaturally blurred. Nice contrast in b&w. Beautiful mountainscape.', '2004-05-02 16:58:34.000000', NULL, 1),
(693764, 71676, 1031, '<td valign="top">I might try and rotate a bit to the left to get the axis of the center windows vertical ... nevermind! I checked and I think that the rocks on the left and the lighting are creating an illusion of tilt, but the center is quite vertical -- nice job!</td>', 'I might try and rotate a bit to the left to get the axis of the center windows vertical ... nevermind! I checked and I think that the rocks on the left and the lighting are creating an illusion of tilt, but the center is quite vertical -- nice job!', '2004-05-02 16:58:42.000000', NULL, 1),
(693765, 72055, 1031, '<td valign="top">The drift of spray framing the building makes for a nice effect;.</td>', 'The drift of spray framing the building makes for a nice effect;.', '2004-05-02 17:00:22.000000', NULL, 1),
(693766, 72254, 9668, '<td valign="top">I like the heron(?) on top of the post, too bad it isn''t more noticible. Looks like a dreary day, nice harbor.</td>', 'I like the heron(?) on top of the post, too bad it isn''t more noticible. Looks like a dreary day, nice harbor.', '2004-05-02 17:02:10.000000', NULL, 1),
(693772, 72310, 18709, '<td valign="top">Whaatever else, you are an enthusiast. Good picture.</td>', 'Whaatever else, you are an enthusiast. Good picture.', '2004-05-02 17:13:01.000000', NULL, 1),
(693775, 71854, 18709, '<td valign="top">Very atmospheric.</td>', 'Very atmospheric.', '2004-05-02 17:14:04.000000', NULL, 1),
(693777, 71667, 18709, '<td valign="top">Very dramatic.  I don''t think I have seen these on my visits.</td>', 'Very dramatic.  I don''t think I have seen these on my visits.', '2004-05-02 17:15:50.000000', NULL, 1),
(693778, 72037, 18709, '<td valign="top">This is so much like ''the movies'' to me that it seems hard to imagine that you live amidst it all.  No doubt you do.</td>', 'This is so much like ''the movies'' to me that it seems hard to imagine that you live amidst it all.  No doubt you do.', '2004-05-02 17:17:18.000000', NULL, 1),
(693780, 71670, 16739, '<td valign="top">very good !</td>', 'very good !', '2004-05-02 17:17:47.000000', NULL, 1),
(693781, 71993, 16739, '<td valign="top">great shot</td>', 'great shot', '2004-05-02 17:18:39.000000', NULL, 1),
(693783, 71634, 16739, '<td valign="top">i like the foul line that ties into the foul pole good shot  , go yanks</td>', 'i like the foul line that ties into the foul pole good shot  , go yanks', '2004-05-02 17:20:00.000000', NULL, 1),
(693784, 72332, 18709, '<td valign="top">A nice spring-like shot.  I take it that you have shown the best part of t he building, and to show any more might spoil things a little.</td>', 'A nice spring-like shot.  I take it that you have shown the best part of t he building, and to show any more might spoil things a little.', '2004-05-02 17:20:02.000000', NULL, 1),
(693785, 71482, 18709, '<td valign="top">A nice shot.  I think I might have shown a bit more sky, and a bit less river, but that''s just personal.</td>', 'A nice shot.  I think I might have shown a bit more sky, and a bit less river, but that''s just personal.', '2004-05-02 17:21:41.000000', NULL, 1),
(693787, 71240, 18709, '<td valign="top">Very good shot.  You don''t have to go out of town to find it.</td>', 'Very good shot.  You don''t have to go out of town to find it.', '2004-05-02 17:22:37.000000', NULL, 1),
(693789, 72170, 18709, '<td valign="top">This is a pretty damning picture, Fortunately I know the other Glasgow, with wonderful municipal buildings and good houses.  This guy looks pretty well-dressed to be sleeping rough?</td>', 'This is a pretty damning picture, Fortunately I know the other Glasgow, with wonderful municipal buildings and good houses.  This guy looks pretty well-dressed to be sleeping rough?', '2004-05-02 17:24:28.000000', NULL, 1),
(693790, 71728, 18709, '<td valign="top">A beautiful night shot, and a wonderful contrast between the modern house and the traditional church.   Very good indeed.</td>', 'A beautiful night shot, and a wonderful contrast between the modern house and the traditional church.   Very good indeed.', '2004-05-02 17:25:31.000000', NULL, 1),
(693791, 71731, 18709, '<td valign="top">The sign says it all.  I hope it''s not quite that bad.</td>', 'The sign says it all.  I hope it''s not quite that bad.', '2004-05-02 17:26:16.000000', NULL, 1),
(693793, 72133, 18709, '<td valign="top">What an interesting collection.  Which one is yours?</td>', 'What an interesting collection.  Which one is yours?', '2004-05-02 17:27:13.000000', NULL, 1),
(693795, 72134, 18709, '<td valign="top">I know the feeling.  Surrounded by sea,</td>', 'I know the feeling.  Surrounded by sea,', '2004-05-02 17:27:50.000000', NULL, 1),
(693798, 72208, 18709, '<td valign="top">I will forego the pleasure.  Good shot. It looks sleazy and uninviting in daylight.</td>', 'I will forego the pleasure.  Good shot. It looks sleazy and uninviting in daylight.', '2004-05-02 17:28:54.000000', NULL, 1),
(693799, 72322, 18709, '<td valign="top">The title says it.</td>', 'The title says it.', '2004-05-02 17:29:21.000000', NULL, 1),
(693801, 71339, 18709, '<td valign="top">Wonderful colours. Nice perspective.</td>', 'Wonderful colours. Nice perspective.', '2004-05-02 17:29:59.000000', NULL, 1),
(693802, 72136, 1031, '<td valign="top">Given that the Advanced Editing rules applied, I think I''d have cropped it just above the cars and cloned out the "Parking" sign in the right foreground. As an architectural photo I''d like it better without the banner, but for representing your area now I guess it''s appropriate. I do like the lighting.</td>', 'Given that the Advanced Editing rules applied, I think I''d have cropped it just above the cars and cloned out the "Parking" sign in the right foreground. As an architectural photo I''d like it better without the banner, but for representing your area now I guess it''s appropriate. I do like the lighting.', '2004-05-02 17:30:28.000000', NULL, 1),
(693804, 72289, 18709, '<td valign="top">This is one of those rare pictures of a place that looks completely wild and   untouched.  Well-taken.</td>', 'This is one of those rare pictures of a place that looks completely wild and   untouched.  Well-taken.', '2004-05-02 17:31:58.000000', NULL, 1),
(693805, 72325, 18709, '<td valign="top">Small population at the moment.   Nice shot.</td>', 'Small population at the moment.   Nice shot.', '2004-05-02 17:32:40.000000', NULL, 1),
(693806, 72206, 1031, '<td valign="top">Still looks kind of cold, but a "cool" spot anyway.</td>', 'Still looks kind of cold, but a "cool" spot anyway.', '2004-05-02 17:33:43.000000', NULL, 1),
(693807, 72232, 18709, '<td valign="top">An interesting shot.   It would have been easy to give it more sky, but that would have been wrong.  It''s just right as it is.</td>', 'An interesting shot.   It would have been easy to give it more sky, but that would have been wrong.  It''s just right as it is.', '2004-05-02 17:34:00.000000', NULL, 1),
(693809, 72139, 18709, '<td valign="top">It is difficult to judge this one.   I would like the baby to have been in better focus,<br/>but then the baby is not the subject.  What is behind the baby is the subject, and you can barely see that at all.</td>', 'It is difficult to judge this one.   I would like the baby to have been in better focus,but then the baby is not the subject.  What is behind the baby is the subject, and you can barely see that at all.', '2004-05-02 17:35:40.000000', NULL, 1),
(693810, 71361, 18709, '<td valign="top">Nice spring-time shot.  colours are good.  Sky a bit grey, but you can only picture what''s there.</td>', 'Nice spring-time shot.  colours are good.  Sky a bit grey, but you can only picture what''s there.', '2004-05-02 17:36:57.000000', NULL, 1),
(693811, 72156, 18709, '<td valign="top">Amazing shot.   Suspended animation.   I hope it''s climbing?</td>', 'Amazing shot.   Suspended animation.   I hope it''s climbing?', '2004-05-02 17:37:46.000000', NULL, 1),
(693816, 72266, 18709, '<td valign="top">I would like to have seen some people there to give it scale.   I take it it is pretty big.<br/>but, big as it is  it is dwarfed by the mountains.</td>', 'I would like to have seen some people there to give it scale.   I take it it is pretty big.but, big as it is  it is dwarfed by the mountains.', '2004-05-02 17:39:43.000000', NULL, 1),
(693819, 72260, 1031, '<td valign="top">Pretty good detail considering how dark and foggy it is<br/> <br/> I think the dark foreground on the very left is a little distracting from the main subjects; you might want to try a square crop starting just to the left of the boat to direct attention more towards the river and its "denizens."<br/> <br/>Another possibility would be to crop off a bunch of sky and give it a panoramic aspect to emphasize the width of the river and bridge.</td>', 'Pretty good detail considering how dark and foggy it is  I think the dark foreground on the very left is a little distracting from the main subjects; you might want to try a square crop starting just to the left of the boat to direct attention more towards the river and its "denizens." Another possibility would be to crop off a bunch of sky and give it a panoramic aspect to emphasize the width of the river and bridge.', '2004-05-02 17:41:39.000000', NULL, 1),
(693821, 71902, 18709, '<td valign="top">An attractive shot.   Gardens are difficult because they tend to descend into <br/>cliche.  But this one is unusual.  The blue of the irises is startling s is the yellow of<br/>the house.</td>', 'An attractive shot.   Gardens are difficult because they tend to descend into cliche.  But this one is unusual.  The blue of the irises is startling s is the yellow ofthe house.', '2004-05-02 17:41:51.000000', NULL, 1),
(693825, 72252, 18709, '<td valign="top">Interesting shot, but not a lot of interest in the structure. especially as the higher it gets, the more like its background it becomes.</td>', 'Interesting shot, but not a lot of interest in the structure. especially as the higher it gets, the more like its background it becomes.', '2004-05-02 17:43:21.000000', NULL, 1),
(693826, 72087, 1031, '<td valign="top">Looks like it could be in a brochure for the seaside restaurant.</td>', 'Looks like it could be in a brochure for the seaside restaurant.', '2004-05-02 17:43:28.000000', NULL, 1),
(693828, 72213, 18709, '<td valign="top">I don''t usually like pictures of parts of buildings, but this one comes off.  It looks friendly and inviting.</td>', 'I don''t usually like pictures of parts of buildings, but this one comes off.  It looks friendly and inviting.', '2004-05-02 17:44:42.000000', NULL, 1),
(693829, 72284, 1031, '<td valign="top">Beautiful job with the detail in the dark tones. I''m not usually that big a fan of the blurred-water look, but it goes well with the sharply-defined rocks.</td>', 'Beautiful job with the detail in the dark tones. I''m not usually that big a fan of the blurred-water look, but it goes well with the sharply-defined rocks.', '2004-05-02 17:45:44.000000', NULL, 1),
(693832, 72011, 1031, '<td valign="top">Good use of panoramic aspect, I like the lighting.</td>', 'Good use of panoramic aspect, I like the lighting.', '2004-05-02 17:47:41.000000', NULL, 1),
(693836, 72257, 1031, '<td valign="top">Nice composition of repeating shapes; an example of "abstract" using recognizable objects.</td>', 'Nice composition of repeating shapes; an example of "abstract" using recognizable objects.', '2004-05-02 17:53:38.000000', NULL, 1),
(693838, 72338, 1031, '<td valign="top">Good time to selectively decolorize and use the square crop.</td>', 'Good time to selectively decolorize and use the square crop.', '2004-05-02 17:56:14.000000', NULL, 1),
(693842, 71670, 1031, '<td valign="top">For pests they''re mighty cute though.</td>', 'For pests they''re mighty cute though.', '2004-05-02 17:58:17.000000', NULL, 1),
(693843, 72334, 1031, '<td valign="top">Looks relaxing once you fix that bench!</td>', 'Looks relaxing once you fix that bench!', '2004-05-02 17:59:10.000000', NULL, 1),
(693845, 72133, 1031, '<td valign="top">Love the auger! Good exposure/tone range.</td>', 'Love the auger! Good exposure/tone range.', '2004-05-02 18:02:21.000000', NULL, 1),
(693847, 71761, 1031, '<td valign="top">Brrrr....excellent exposure, incredible DOF.</td>', 'Brrrr....excellent exposure, incredible DOF.', '2004-05-02 18:05:54.000000', NULL, 1),
(693849, 72072, 637, '<td valign="top">Makes me nostalgic</td>', 'Makes me nostalgic', '2004-05-02 18:07:35.000000', NULL, 1),
(693850, 72002, 1031, '<td valign="top">That''s some really good lighting you took advantage of -- good job.</td>', 'That''s some really good lighting you took advantage of -- good job.', '2004-05-02 18:07:42.000000', NULL, 1),
(693854, 72144, 1031, '<td valign="top">That looks just like a building designed for Superman to leap over ... good use of the trees and clouds to frame a really cool piece of architecture.</td>', 'That looks just like a building designed for Superman to leap over ... good use of the trees and clouds to frame a really cool piece of architecture.', '2004-05-02 18:11:53.000000', NULL, 1),
(693856, 72165, 1209, '<td valign="top">Lucky you! Beautiful place and nice photo!</td>', 'Lucky you! Beautiful place and nice photo!', '2004-05-02 18:14:03.000000', NULL, 1),
(693857, 72110, 1209, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2004-05-02 18:14:43.000000', NULL, 1),
(693861, 71715, 1209, '<td valign="top">Lovely!</td>', 'Lovely!', '2004-05-02 18:18:00.000000', NULL, 1),
(693863, 72264, 11738, '<td valign="top">Too bad about the keystoning in the tower.  You could have easily corrected this in Photoshop with the Free Transform function since this was Advance edit rules.  I would like to see the corrected version.  Good capture</td>', 'Too bad about the keystoning in the tower.  You could have easily corrected this in Photoshop with the Free Transform function since this was Advance edit rules.  I would like to see the corrected version.  Good capture', '2004-05-02 18:21:44.000000', NULL, 1),
(693872, 71688, 14986, '<td valign="top">Just not much interest for me at all with this shot.</td>', 'Just not much interest for me at all with this shot.', '2004-05-02 18:30:14.000000', NULL, 1),
(693874, 72134, 14986, '<td valign="top">Nice photo...I even like the border - but a 20 word title?</td>', 'Nice photo...I even like the border - but a 20 word title?', '2004-05-02 18:31:42.000000', NULL, 1),
(693875, 71715, 14986, '<td valign="top">Nice shot I think, except for the tilt.  I would rotate a bit counter clockwise.</td>', 'Nice shot I think, except for the tilt.  I would rotate a bit counter clockwise.', '2004-05-02 18:32:33.000000', NULL, 1),
(693877, 72338, 14986, '<td valign="top">Nice use of dof and having the blue box stand out.</td>', 'Nice use of dof and having the blue box stand out.', '2004-05-02 18:33:38.000000', NULL, 1),
(693881, 72293, 14986, '<td valign="top">Nice, clear, uncluttered shot.</td>', 'Nice, clear, uncluttered shot.', '2004-05-02 18:34:36.000000', NULL, 1),
(693883, 71667, 14986, '<td valign="top">I think this is way too contrasty....you lose just about all the details.  It is an intersting perspective for the shot, though.</td>', 'I think this is way too contrasty....you lose just about all the details.  It is an intersting perspective for the shot, though.', '2004-05-02 18:35:13.000000', NULL, 1),
(693885, 72245, 14986, '<td valign="top">Kind of a cool feel with the gray tones of this shot.  I would correct the tilt.</td>', 'Kind of a cool feel with the gray tones of this shot.  I would correct the tilt.', '2004-05-02 18:36:17.000000', NULL, 1),
(693886, 72133, 14986, '<td valign="top">Intereting quartet of boxes...with the different bases.  I think you have a good tonal range in the b/w and nice clear focus.  Good job!</td>', 'Intereting quartet of boxes...with the different bases.  I think you have a good tonal range in the b/w and nice clear focus.  Good job!', '2004-05-02 18:37:32.000000', NULL, 1),
(693887, 72223, 14986, '<td valign="top">Nice shot using the trees to frame up the skyline.</td>', 'Nice shot using the trees to frame up the skyline.', '2004-05-02 18:38:07.000000', NULL, 1),
(693889, 71123, 772, '<td valign="top">This is a beautiful photo.  It''s hard for me to associate Brooklyn with this level of peace and solitude though.  This aspect, however, makes this quite appealing to me :)  Great shot... = 10</td>', 'This is a beautiful photo.  It''s hard for me to associate Brooklyn with this level of peace and solitude though.  This aspect, however, makes this quite appealing to me :)  Great shot... = 10', '2004-05-02 18:39:37.000000', NULL, 1),
(693890, 71581, 14986, '<td valign="top">I really like the creativity of using this shot.   I wish there was some way to bring the engraving out a little more, but to crop it you would lose the colors.   Anyway, this is one of my favorites of the challenge.</td>', 'I really like the creativity of using this shot.   I wish there was some way to bring the engraving out a little more, but to crop it you would lose the colors.   Anyway, this is one of my favorites of the challenge.', '2004-05-02 18:40:33.000000', NULL, 1),
(693892, 72126, 14986, '<td valign="top">Very nice composition and feel to the shot.  I think the border is way overpowering.</td>', 'Very nice composition and feel to the shot.  I think the border is way overpowering.', '2004-05-02 18:41:08.000000', NULL, 1),
(693893, 72122, 9581, '<td valign="top">Te reflections and glares of trees take away from the building</td>', 'Te reflections and glares of trees take away from the building', '2004-05-02 18:41:30.000000', NULL, 1),
(693894, 71588, 14986, '<td valign="top">Nice, clear shot with excellent colors.   Some people may not like the polarizing effect, but I like the way it really brings out the colors.</td>', 'Nice, clear shot with excellent colors.   Some people may not like the polarizing effect, but I like the way it really brings out the colors.', '2004-05-02 18:42:32.000000', NULL, 1),
(693896, 72324, 9581, '<td valign="top">a little dark and picture is small</td>', 'a little dark and picture is small', '2004-05-02 18:42:36.000000', NULL, 1),
(693898, 71993, 14986, '<td valign="top">Really nice perspective.  I would have had just a few less flowers in the foreground (cropping just slightly at the bottom) and I would definitely lose the border.  I''m not against borders at all, but this one really seems to overcome the nice photo.</td>', 'Really nice perspective.  I would have had just a few less flowers in the foreground (cropping just slightly at the bottom) and I would definitely lose the border.  I''m not against borders at all, but this one really seems to overcome the nice photo.', '2004-05-02 18:44:17.000000', NULL, 1),
(693899, 72300, 14986, '<td valign="top">Cool subject, but I think the photo overall is too dark.</td>', 'Cool subject, but I think the photo overall is too dark.', '2004-05-02 18:44:56.000000', NULL, 1),
(693902, 72239, 14986, '<td valign="top">A good try but I don''t care for it.  I think part of the reason is that the colors are kinda blah.  Nothing really there to catch your eye once, much less two or three times.   I also might have liked it better with the glass not on the ground...maybe on a stone wall or something with some interest.  It would have been nice to capture more of that tree in the glass as well.</td>', 'A good try but I don''t care for it.  I think part of the reason is that the colors are kinda blah.  Nothing really there to catch your eye once, much less two or three times.   I also might have liked it better with the glass not on the ground...maybe on a stone wall or something with some interest.  It would have been nice to capture more of that tree in the glass as well.', '2004-05-02 18:47:44.000000', NULL, 1),
(693907, 71634, 14986, '<td valign="top">Really nice catch of the identical batting stances.  I''m a big baseball fan, so I like seeing shots like this.   good choice of dof so both are in forcus.  I even like having the third base umpire right down the line.   Composition makes this shot.  (Did ya win?)</td>', 'Really nice catch of the identical batting stances.  I''m a big baseball fan, so I like seeing shots like this.   good choice of dof so both are in forcus.  I even like having the third base umpire right down the line.   Composition makes this shot.  (Did ya win?)', '2004-05-02 18:49:23.000000', NULL, 1),
