(694237, 72336, 3102, '<td valign="top">One of my top picks for the week -- way to go!</td>', 'One of my top picks for the week -- way to go!', '2004-05-03 01:02:30.000000', NULL, 0),
(694238, 71124, 3102, '<td valign="top">Hey, if I''m gonna be beat, it may as well be by this one!  This was one of my few 10s this time... congrats!!</td>', 'Hey, if I''m gonna be beat, it may as well be by this one!  This was one of my few 10s this time... congrats!!', '2004-05-03 01:03:08.000000', NULL, 0),
(694239, 72336, 327, '<td valign="top">Congrats. Just a super all around shot. Fantastic colors.<br/>Love it!</td>', 'Congrats. Just a super all around shot. Fantastic colors.Love it!', '2004-05-03 01:03:14.000000', NULL, 0),
(694240, 71124, 11181, '<td valign="top">Congrats! Looks like all the pics i rated 10 got into the top 3! Well deserved ribbon!</td>', 'Congrats! Looks like all the pics i rated 10 got into the top 3! Well deserved ribbon!', '2004-05-03 01:03:16.000000', NULL, 0),
(694241, 71124, 16301, '<td valign="top">"Thank you very much" to everyone for their nice comments, votes, and for giving me my first ribbon. This is my favorite photo, i''m glad you all liked it.<br/> <br/>A larger view can be found <a href="//www.deviantart.com/view/7007362/" rel="nofollow" target="_blank">here</a> <br/> <br/>- Thamer<br/><br/><i>Message edited by author 2004-05-03 15:01:06.</i></td>', '"Thank you very much" to everyone for their nice comments, votes, and for giving me my first ribbon. This is my favorite photo, i''m glad you all liked it. A larger view can be found here  - Thamer', '2004-05-03 01:03:57.000000', '2004-05-03 16:01:06.000000', 0),
(694242, 72336, 6870, '<td valign="top">Hey Tom, juicy! I love this. Congratulations on the ribbon!</td>', 'Hey Tom, juicy! I love this. Congratulations on the ribbon!', '2004-05-03 01:04:02.000000', NULL, 0),
(694245, 71124, 6870, '<td valign="top">Super, super work. Congratulations!</td>', 'Super, super work. Congratulations!', '2004-05-03 01:05:13.000000', NULL, 0),
(694247, 72068, 6870, '<td valign="top">Go Alan! Nice work and congratulations!</td>', 'Go Alan! Nice work and congratulations!', '2004-05-03 01:06:07.000000', NULL, 0),
(694249, 72068, 16301, '<td valign="top">Congrats on the well deserved ribbon, definitely one of the unique photos in the challenge.<br/> <br/>Keep it up...</td>', 'Congrats on the well deserved ribbon, definitely one of the unique photos in the challenge. Keep it up...', '2004-05-03 01:07:01.000000', NULL, 0),
(694250, 72336, 14986, '<td valign="top">Hey...I actually got this one right!   You were up against some very good shots, and I''m glad this one won.  Congratulations.</td>', 'Hey...I actually got this one right!   You were up against some very good shots, and I''m glad this one won.  Congratulations.', '2004-05-03 01:07:58.000000', NULL, 0),
