INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(694255, 72169, 16301, '<td valign="top">I gave this a 9 and thought it was gonna get a ribbon. A really great photo...</td>', 'I gave this a 9 and thought it was gonna get a ribbon. A really great photo...', '2004-05-03 01:09:48.000000', NULL, 0),
(694260, 72336, 20509, '<td valign="top">This is an awesome photo.  I love it.  I''ve lived all over California my whole life and am sick of the derogatory things said on the news about it.  Yes, the cost of living is more here.  Yes, SOME people are egocentric and arrogant.  Yes, there''s smog and the governor is an actor, but I still think every negative word said is out of jealousy.  CALIFORNIA ROCKS!...and its VERY beautiful and you have done it justice.<br/> <br/>Thanks.  Oceanside rocks too, btw.</td>', 'This is an awesome photo.  I love it.  I''ve lived all over California my whole life and am sick of the derogatory things said on the news about it.  Yes, the cost of living is more here.  Yes, SOME people are egocentric and arrogant.  Yes, there''s smog and the governor is an actor, but I still think every negative word said is out of jealousy.  CALIFORNIA ROCKS!...and its VERY beautiful and you have done it justice. Thanks.  Oceanside rocks too, btw.', '2004-05-03 01:11:37.000000', NULL, 0),
(694261, 72284, 6405, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by pitsaman:</b></div><hr/><i> Looks like JmSetzlers photo,well done b/w.10 from me ! </i></td></tr></table> <br/> <br/>You can''t hide from me ! :-)</td>', 'Originally posted by pitsaman: Looks like JmSetzlers photo,well done b/w.10 from me !   You can''t hide from me ! :-)', '2004-05-03 01:12:02.000000', NULL, 0),
(694263, 72336, 16301, '<td valign="top">The display of different elements in this photo is just beautiful. Nice to see it got 1st place.<br/> <br/>Great work...</td>', 'The display of different elements in this photo is just beautiful. Nice to see it got 1st place. Great work...', '2004-05-03 01:12:16.000000', NULL, 0),
(694267, 72144, 3102, '<td valign="top">Ah -- Thought this might have been done by my buddy Mike (Lycafos) since he lives right near there!  I, too, "lived" there for a few years, but not as a student.  My office was right across the street, beside Soldiers and Sailor''s Hall.  Glad to see this did pretty well... that''s a pretty cool building to shoot.</td>', 'Ah -- Thought this might have been done by my buddy Mike (Lycafos) since he lives right near there!  I, too, "lived" there for a few years, but not as a student.  My office was right across the street, beside Soldiers and Sailor''s Hall.  Glad to see this did pretty well... that''s a pretty cool building to shoot.', '2004-05-03 01:13:58.000000', NULL, 0),
(694268, 72068, 11078, '<td valign="top">Congrats! Just knew this was a winner well done</td>', 'Congrats! Just knew this was a winner well done', '2004-05-03 01:14:03.000000', NULL, 0),
(694272, 72119, 12448, '<td valign="top">Excellent shot, congrats on 4th place but it should have been first!  This is a fantastic shot, so much emotion, life and feeling.<br/> <br/>Deannda</td>', 'Excellent shot, congrats on 4th place but it should have been first!  This is a fantastic shot, so much emotion, life and feeling. Deannda', '2004-05-03 01:14:42.000000', NULL, 0),
(694294, 72119, 16301, '<td valign="top">Heida,<br/> <br/>I knew this was your photo and I knew it would finish in the top ten.<br/> <br/>Congrats, hopefuly a ribbon next time :)</td>', 'Heida, I knew this was your photo and I knew it would finish in the top ten. Congrats, hopefuly a ribbon next time :)', '2004-05-03 01:18:21.000000', NULL, 0),
(694309, 72260, 13035, '<td valign="top">well, i don''t always pick right, but this shot goes to my favororites.  Show me this one some time in a sepia tone.  Keep shooting! regards, russ</td>', 'well, i don''t always pick right, but this shot goes to my favororites.  Show me this one some time in a sepia tone.  Keep shooting! regards, russ', '2004-05-03 01:21:01.000000', NULL, 0),
(694313, 72169, 6870, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tyt2000:</b></div><hr/><i> I gave this a 9 and thought it was gonna get a ribbon. A really great photo... </i></td></tr></table> <br/> <br/>Very nice of you, but wow! there are so many great photos in this challenge. I''m lucky to get 11th in my opinion!</td>', 'Originally posted by tyt2000: I gave this a 9 and thought it was gonna get a ribbon. A really great photo...   Very nice of you, but wow! there are so many great photos in this challenge. I''m lucky to get 11th in my opinion!', '2004-05-03 01:21:33.000000', NULL, 0),
(694335, 72230, 13035, '<td valign="top">13th ain''t bad.  I hope you are pleased.  Congratulations again on a great capture.  russ</td>', '13th ain''t bad.  I hope you are pleased.  Congratulations again on a great capture.  russ', '2004-05-03 01:24:24.000000', NULL, 0),
(694338, 71571, 12268, '<td valign="top">Getting a lot better here! Just added to my faves! I really like teh compo &amp; wish there was a bit more detail to the flowers. Would love to see some outtakes if ya got any!<br/>Dunno whats up with the voting... crazy haters! Good stuff!</td>', 'Getting a lot better here! Just added to my faves! I really like teh compo & wish there was a bit more detail to the flowers. Would love to see some outtakes if ya got any!Dunno whats up with the voting... crazy haters! Good stuff!', '2004-05-03 01:24:45.000000', NULL, 0),
(694351, 72002, 13035, '<td valign="top">Had you higher, but 14th is the best that I''ve ever done.  Congratulations again on a wonderful shot.  russ</td>', 'Had you higher, but 14th is the best that I''ve ever done.  Congratulations again on a wonderful shot.  russ', '2004-05-03 01:27:07.000000', NULL, 0),
(694381, 72169, 3102, '<td valign="top">Dang -- I swore this would be Top 10 material in my original comment, and I was quite sure of myself!  Frankly I would have expected this to be in the Top 3, let alone Top 10!  It''s an awesome shot -- should be hanging on a wall someplace.</td>', 'Dang -- I swore this would be Top 10 material in my original comment, and I was quite sure of myself!  Frankly I would have expected this to be in the Top 3, let alone Top 10!  It''s an awesome shot -- should be hanging on a wall someplace.', '2004-05-03 01:30:57.000000', NULL, 0),
(694397, 71634, 13035, '<td valign="top">176 entries, and maybe 5 that attempted to show anything to do with the culture.  Funny, my guide book goes about 50/50 for shots of scenery compared to shots of culture awareness.  DPC is a homogenized community.  Majority rules here.  20th isn''t bad, but in my contest you were in the top 5.  Congratulations on a high finish.  russ</td>', '176 entries, and maybe 5 that attempted to show anything to do with the culture.  Funny, my guide book goes about 50/50 for shots of scenery compared to shots of culture awareness.  DPC is a homogenized community.  Majority rules here.  20th isn''t bad, but in my contest you were in the top 5.  Congratulations on a high finish.  russ', '2004-05-03 01:32:43.000000', NULL, 0),
(694433, 71883, 13035, '<td valign="top">I''ve got you a lot higher than 21, but congratulations on a very nice finish.  I love your picture.  ¡saludos de méxico!..russ</td>', 'I''ve got you a lot higher than 21, but congratulations on a very nice finish.  I love your picture.  ¡saludos de méxico!..russ', '2004-05-03 01:37:00.000000', NULL, 0),
(694528, 72336, 20779, '<td valign="top">YIPPEE! This was my first challenge and this is the ONE I kept coming back to look at!!!!!! I''ll buy it if you sell it!!!!!</td>', 'YIPPEE! This was my first challenge and this is the ONE I kept coming back to look at!!!!!! I''ll buy it if you sell it!!!!!', '2004-05-03 01:55:35.000000', NULL, 0),
(694540, 72230, 1031, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by jpochard:</b></div><hr/><i> I really like the sense of movement this shot has from the leaning of the tall grass.   With the fence post going in the opposite diagonal, it''s a nice contrast.    Very good composition.   I think I might like it better with just a little more contrast to the tone. </i></td></tr></table> <br/>This was just my reaction too; not MUCH more tone range though, because I like how much detail you''ve depicted with a limited palette ... a very difficult effect to pull off as well as you have here.</td>', 'Originally posted by jpochard: I really like the sense of movement this shot has from the leaning of the tall grass.   With the fence post going in the opposite diagonal, it''s a nice contrast.    Very good composition.   I think I might like it better with just a little more contrast to the tone.  This was just my reaction too; not MUCH more tone range though, because I like how much detail you''ve depicted with a limited palette ... a very difficult effect to pull off as well as you have here.', '2004-05-03 01:58:49.000000', NULL, 0),
(694587, 72336, 3599, '<td valign="top">Hey, Congratulations!  Like I said before my favorite and I am glad you got the blue ribbon.</td>', 'Hey, Congratulations!  Like I said before my favorite and I am glad you got the blue ribbon.', '2004-05-03 02:12:33.000000', NULL, 0),
